def lazy_tab_select(labels, key):
    """Drop-in for st.tabs: pill buttons that return the INDEX of the open section, so only that section's code runs
    (st.tabs runs every tab on every click). Use:  _tab = lazy_tab_select([...], "lz_x");  if _tab == 0: ..."""
    st.markdown(_LZ_CSS, unsafe_allow_html=True)
    choice = st.radio(key, labels, horizontal=True, key=key, label_visibility="collapsed")
    return labels.index(choice) if choice in labels else 0


def run(sql, params=None):
    conn = get_conn()
    t0 = time.perf_counter()
    try:
        with conn.cursor() as cur:
            cur.execute(sql, params)
            return cur.fetchall() if cur.description else None
    except Exception:
        conn.rollback()
        raise
    finally:
        _db_note(sql, time.perf_counter() - t0)


def tx(fn):
    """Database write: commit on success, rollback on any error."""
    @functools.wraps(fn)
    def inner(*a, **k):
        conn = get_conn()
        try:
            res = fn(*a, **k)
            _t0 = time.perf_counter()
            conn.commit()
            _db_note("COMMIT", time.perf_counter() - _t0)
            return True if res is None else res
        except Exception as e:
            conn.rollback()
            st.error(f"❌ Database error (rollback kora holo): {e}")
            return None
    return inner


def fw(fac, alias=""):
    """Factory filter. CONSOLIDATED / None = no filter."""
    if not fac or "CONSOLIDATED" in fac:
        return "", []
    return f" AND {alias}factory_name=%s", [fac]


