# ---------- Stay logged in after a browser refresh ----------
# A browser refresh starts a brand-new Streamlit session, so st.session_state is empty. After a successful login a random
# token is stored (hashed) in the database and in a browser cookie; on refresh the cookie is checked and the login restored.
SESSION_COOKIE = "kcw_session"
SESSION_HOURS = 12


def _tok_hash(tok):
    return hashlib.sha256(tok.encode()).hexdigest()


def _cookie_token():
    try:
        return st.context.cookies.get(SESSION_COOKIE) or ""
    except Exception:   # Streamlit older than 1.37 has no st.context.cookies -> no auto re-login, nothing else changes
        return ""


@tx
def create_login_session(username):
    tok = secrets.token_urlsafe(32)
    now = datetime.now()
    run("DELETE FROM login_sessions WHERE expires_at < %s", (now.strftime("%Y-%m-%d %H:%M:%S"),))
    run("INSERT INTO login_sessions (token_hash, username, created_at, expires_at) VALUES (%s,%s,%s,%s)",
        (_tok_hash(tok), username, now.strftime("%Y-%m-%d %H:%M:%S"),
         (now + timedelta(hours=SESSION_HOURS)).strftime("%Y-%m-%d %H:%M:%S")))
    return tok


UNIT_LOCK_ROLES = ("Store Officer",)   # roles that must pick one unit after login; it stays locked until sign-out


@tx
def save_session_factory(fac):
    """Binds the chosen unit to this login session (survives a page reload through the session cookie)."""
    tok = st.session_state.get("_login_tok") or _cookie_token()
    if tok:
        run("ALTER TABLE login_sessions ADD COLUMN IF NOT EXISTS factory TEXT DEFAULT ''")
        run("UPDATE login_sessions SET factory=%s WHERE token_hash=%s", (fac, _tok_hash(tok)))
    return True


@tx
def end_login_session():
    for tok in {st.session_state.get("_login_tok") or "", _cookie_token()}:
        if tok:
            run("DELETE FROM login_sessions WHERE token_hash=%s", (_tok_hash(tok),))
    return True


def restore_login_from_cookie():
    """Runs at the start of every session: if nobody is logged in but a valid session cookie exists, log that user back in."""
    if st.session_state.get("user"):
        return
    tok = _cookie_token()
    if not tok:
        return
    try:
        r = q("""SELECT s.username, u.role, COALESCE(u.status,'Active') AS status
                 FROM login_sessions s JOIN users u ON u.username=s.username
                 WHERE s.token_hash=%s AND s.expires_at > %s""",
              (_tok_hash(tok), datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
    except Exception:
        return
    if r and r[0]["status"] == "Active":
        st.session_state["user"] = r[0]["username"]
        st.session_state["role"] = r[0]["role"]
        st.session_state["_login_tok"] = tok
        if r[0]["role"] in UNIT_LOCK_ROLES:   # a reload must not release the unit lock
            try:
                f = q("SELECT COALESCE(factory,'') AS factory FROM login_sessions WHERE token_hash=%s", (_tok_hash(tok),))
                if f and f[0]["factory"] in FACTORIES:
                    st.session_state["locked_factory"] = f[0]["factory"]
            except Exception:
                pass


def render_session_cookie_js():
    """Writes (after login) or removes (after logout) the session cookie in the browser. Invisible, runs once."""
    tok = st.session_state.pop("_cookie_set", None)
    clear = st.session_state.pop("_cookie_clear", None)
    if tok:
        val, age = tok, SESSION_HOURS * 3600
    elif clear:
        val, age = "", 0
    else:
        return
    components.html(
        f"""<script>
        try {{
          const d = window.parent.document;
          const sec = window.parent.location.protocol === 'https:' ? '; Secure' : '';
          d.cookie = "{SESSION_COOKIE}={val}; path=/; max-age={age}; SameSite=Lax" + sec;
        }} catch (e) {{}}
        </script>""", height=0)


def render_login_control():
    """Compact top-bar account popover with Sign in, Register and Forgot password tabs."""
    logged_in = bool(st.session_state.get("user"))
    label = f"👤 {st.session_state.get('user', 'Account')}" if logged_in else "🔐 Secure Login"
    with st.popover(label, use_container_width=True):
        if logged_in:
            st.markdown(f"**{html_lib.escape(str(st.session_state.get('user', '')))}**")
            st.caption(html_lib.escape(str(st.session_state.get("role", ""))))
            if st.button("🚪 Sign out", key="top_logout_btn", use_container_width=True):
                log_event("LOGOUT", f"User {st.session_state['user']} logged out.")
                end_login_session()
                st.session_state.pop("user", None)
                st.session_state.pop("role", None)
                st.session_state.pop("locked_factory", None)   # unit lock ends with the login session
                st.session_state.pop("_login_tok", None)
                st.session_state.pop("_gate_pending", None)
                st.session_state["_cookie_clear"] = True
                done("Signed out successfully.")
            with st.expander("🔑 Change password"):
                with st.form("chg_pw_form", clear_on_submit=True):
                    cur_pw = st.text_input("Current password", type="password", key="cp_cur")
                    new_pw1 = st.text_input("New password (min 8 chars)", type="password", key="cp_new1")
                    new_pw2 = st.text_input("Confirm new password", type="password", key="cp_new2")
                    chg = st.form_submit_button("Update password", use_container_width=True)
                if chg:
                    row = q("SELECT password FROM users WHERE username=%s", (st.session_state["user"],))
                    if not row or not verify_password(row[0]["password"], cur_pw):
                        st.error("Current password is incorrect.")
                    elif len(new_pw1) < 8:
                        st.error("New password must be at least 8 characters.")
                    elif new_pw1 != new_pw2:
                        st.error("The passwords do not match.")
                    elif change_password(st.session_state["user"], new_pw1):
                        st.success("Password updated.")
            if st.session_state.get("role") == "Store Manager":
                user_admin_panel()
            return

        sign_in_tab, register_tab, forgot_tab = st.tabs(["Sign in", "Register", "Forgot password"])
        with sign_in_tab:
            st.caption("Use your approved account to access inventory operations.")
            with st.form("login_form", clear_on_submit=False):
                username = st.text_input("Username", placeholder="Enter your username", key="login_user")
                password = st.text_input("Password", type="password", placeholder="Enter your password", key="login_pass")
                submitted = st.form_submit_button("Sign in", use_container_width=True)
            if submitted:
                if not username.strip() or not password:
                    st.error("Enter both username and password.")
                else:
                    rows = q(
                        "SELECT password, role, COALESCE(status,'Active') AS status FROM users WHERE username=%s",
                        (username.strip(),)
                    )
                    if rows and verify_password(rows[0]["password"], password):
                        if rows[0]["status"] == "Pending":
                            st.warning("Your account is waiting for manager approval.")
                        elif rows[0]["status"] != "Active":
                            st.error("This account is not active. Contact the Store Manager.")
                        else:
                            st.session_state["user"] = username.strip()
                            st.session_state["role"] = rows[0]["role"]
                            st.session_state.pop("locked_factory", None)   # every new login must choose its unit
                            st.session_state.pop("_gate_pending", None)
                            token = create_login_session(username.strip())
                            if token:
                                st.session_state["_cookie_set"] = token
                                st.session_state["_login_tok"] = token
                            log_event("LOGIN", f"User {username.strip()} logged in as {rows[0]['role']}.")
                            done(f"Welcome, {username.strip()}!")
                    else:
                        st.error("Username or password is incorrect.")

        with register_tab:
            st.caption("New accounts require Store Manager approval.")
            with st.form("reg_form", clear_on_submit=True):
                reg_user = st.text_input("Username", key="reg_user", placeholder="3–30 letters, digits, _ . -")
                full_name = st.text_input("Full name", key="reg_name")
                reg_pw1 = st.text_input("Password (min 8 characters)", type="password", key="reg_pw1")
                reg_pw2 = st.text_input("Confirm password", type="password", key="reg_pw2")
                register_submit = st.form_submit_button("Request registration", use_container_width=True)
            if register_submit:
                if not USERNAME_RE.fullmatch(reg_user.strip()):
                    st.error("Username must be 3–30 characters using letters, numbers, _ . or -.")
                elif not full_name.strip():
                    st.error("Enter your full name.")
                elif len(reg_pw1) < 8:
                    st.error("Password must be at least 8 characters.")
                elif reg_pw1 != reg_pw2:
                    st.error("The passwords do not match.")
                elif register_user(reg_user.strip(), full_name.strip(), reg_pw1):
                    st.success("Registration request sent. The Store Manager must approve it before sign-in.")

        with forgot_tab:
            st.caption("Password recovery requests are reviewed by the Store Manager.")
            with st.form("fp_form", clear_on_submit=True):
                reset_user = st.text_input("Username", key="fp_user")
                reset_submit = st.form_submit_button("Request password reset", use_container_width=True)
            if reset_submit:
                if not reset_user.strip():
                    st.error("Enter your username.")
                else:
                    request_password_reset(reset_user.strip())
                    st.success("If the account is active, the reset request has been sent to the Store Manager.")

