def _real_code(c):
    c = str(c or "").strip()
    return bool(c) and not is_blank_code(c) and not c.upper().startswith("TEMP-")


def find_same_item_coded(fac, name, size, code="", exclude_sl=None):
    """Same product = same name + same size. A NO-SIZE item whose real ERP code differs from the new real ERP code
    is a different product (the ERP code tells them apart)."""
    nn, ns = norm_name(name), norm_size(size)
    for r in q("SELECT sl_no, prod_id, item_name, COALESCE(size,'') AS size FROM inventory WHERE factory_name=%s", (fac,)):
        if exclude_sl is not None and r["sl_no"] == exclude_sl:
            continue
        if norm_name(r["item_name"]) == nn and norm_size(r["size"]) == ns:
            if not ns and _real_code(code) and _real_code(r["prod_id"]) \
                    and str(code).strip().lower() != str(r["prod_id"]).strip().lower():
                continue
            return r
    return None


def free_code_variant(fac, base, size):
    """A free ERP code for another size of the same product: CODE-SIZE (CODE-2, CODE-3 ... when there is no size)."""
    s_ = str(size or "").strip()
    n = 1
    cand = f"{base}-{s_}" if s_ else f"{base}-2"
    while q("SELECT 1 AS x FROM inventory WHERE prod_id=%s AND factory_name=%s", (cand, fac)):
        n += 1
        cand = f"{base}-{s_}-{n}" if s_ else f"{base}-{n + 1}"
    return cand


@tx
def add_item_sizes(fac, base_code, name, sizes, dept, cat, stock, price, unit, product_cat):
    """One product in several sizes: one inventory row per size (existing name+size are skipped, never changed)."""
    made, skipped = [], []
    for sz in sizes:
        if find_same_item(fac, name, sz):
            skipped.append(sz)
            continue
        code = free_code_variant(fac, base_code.strip(), sz) if not is_blank_code(base_code) else next_free_temp(fac)
        mx = q("SELECT COALESCE(MAX(sl_no),0) AS m FROM inventory WHERE factory_name=%s", (fac,))[0]["m"]
        run("""INSERT INTO inventory (sl_no, prod_id, factory_name, item_name, size, department, category,
               erp_stock, current_stock, unit_price, erp_status, serial_no, unit_name, product_category)
               VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'ERP Pending',%s,%s,%s)""",
            (int(mx) + 1, code, fac, name, sz, dept, cat, stock, stock, price, "", unit, product_cat or ""))
        mirror_to_other(fac, code, name, sz, dept, cat, price, unit, product_cat)
        made.append(sz)
    audit("ADD_ITEM_SIZES", f"{fac}: {name} sizes added {made}, skipped (already exist) {skipped}")
    return made, skipped


@tx
def add_item(fac, code, name, size, dept, cat, stock, price, serial="", unit="Pcs", product_cat=""):
    """cat = Budget Category (stays in inventory.category exactly as before, so Budget logic is unchanged);
    product_cat = separate Product Category (inventory.product_category)."""
    serial = (serial or "").strip()
    ex = find_same_item_coded(fac, name, size, code)
    owner = serial_owner(fac, serial)
    if owner and (not ex or owner["sl_no"] != ex["sl_no"]):
        st.error(f"Serial '{serial}' already used: SL {owner['sl_no']} ({owner['item_name']} [{owner['size'] or '-'}]).")
        return False
    if ex:  # same name + size already exists -> stock add, no duplicate
        run("""UPDATE inventory SET current_stock=COALESCE(current_stock,0)+%s,
               unit_price=CASE WHEN %s>0 THEN %s ELSE unit_price END WHERE sl_no=%s AND factory_name=%s""",
            (stock, price, price, ex["sl_no"], fac))
        if serial:
            run("UPDATE inventory SET serial_no=%s WHERE sl_no=%s AND factory_name=%s AND COALESCE(serial_no,'')=''",
                (serial, ex["sl_no"], fac))
        if stock > 0:
            now = datetime.now()
            insert_tx(fac, st.session_state["user"], ex["sl_no"], ex["prod_id"], name, stock, "Stock Adjustment (+)",
                      now.day, "Stock added to existing item (Add New Item)", now.strftime(DATE_FMT),
                      now.strftime("%I:%M %p"), "Verified")
        audit("ADD_STOCK_EXISTING", f"{fac}: {name} [{size}] +{stock:g}")
        return ("exists", ex["sl_no"])
    code_given = not is_blank_code(code)
    code = code.strip() if code_given else next_free_temp(fac)
    note = ""
    hit = q("SELECT item_name FROM inventory WHERE prod_id=%s AND factory_name=%s", (code, fac))
    if hit:
        if code_given and norm_name(hit[0]["item_name"]) == norm_name(name):
            # same product, another size sharing the ERP code -> CODE-SIZE (same rule the opening-stock import uses)
            old_code = code
            code = free_code_variant(fac, code, size)
            note = f"ERP Code '{old_code}' is already used by another size of this product, so this size got '{code}'."
        else:
            st.error(f"ERP Code '{code}' already exists in {fac} for a different item ({hit[0]['item_name']}).")
            return False
    mx = q("SELECT COALESCE(MAX(sl_no),0) AS m FROM inventory WHERE factory_name=%s", (fac,))[0]["m"]
    run("""INSERT INTO inventory (sl_no, prod_id, factory_name, item_name, size, department, category,
           erp_stock, current_stock, unit_price, erp_status, serial_no, unit_name, product_category)
           VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'ERP Pending',%s,%s,%s)""",
        (int(mx) + 1, code, fac, name, size, dept, cat, stock, stock, price, serial, unit, product_cat or ""))
    mirrored = mirror_to_other(fac, code, name, size, dept, cat, price, unit, product_cat)
    audit("ADD_ITEM", f"{fac}: {name} [{size}] [{code}] dept={dept} budget_cat={cat} product_cat={product_cat or '-'} UOM {unit}"
          + (f" S/N {serial}" if serial else "")
          + (" + copied to other unit" if mirrored else ""))
    return ("new", int(mx) + 1, code, note)


@tx
def update_item(fac, sl, old_code, old_name, code, name, size, dept, cat, erp, phys, price, unit, serial=""):
    serial = (serial or "").strip()
    dups = [r for r in q("SELECT item_name, COALESCE(size,'') AS size, prod_id FROM inventory "
                         "WHERE factory_name=%s AND sl_no<>%s", (fac, sl))
            if norm_name(r["item_name"]) == norm_name(name) and norm_size(r["size"]) == norm_size(size)]
    if not norm_size(size):   # no size: a different real ERP code means a different product
        dups = [r for r in dups if not (_real_code(code) and _real_code(r["prod_id"])
                                         and str(code).strip().lower() != str(r["prod_id"]).strip().lower())]
    if dups:
        st.error(f"'{name}' [{size or 'no size'}] already exists in {fac}! Give it a size or a different ERP code "
                 f"to tell them apart.")
        return False
    if code != old_code and q("SELECT 1 AS x FROM inventory WHERE factory_name=%s AND prod_id=%s AND sl_no<>%s", (fac, code, sl)):
        st.error(f"ERP Code '{code}' already used!")
        return False
    owner = serial_owner(fac, serial, exclude_sl=sl)
    if owner:
        st.error(f"Serial '{serial}' already used: SL {owner['sl_no']} ({owner['item_name']} [{owner['size'] or '-'}]).")
        return False
    run("""UPDATE inventory SET prod_id=%s, item_name=%s, size=%s, department=%s, category=%s, erp_stock=%s,
           current_stock=%s, unit_price=%s, unit_name=%s, serial_no=%s WHERE sl_no=%s AND factory_name=%s""",
        (code, name, size, dept, cat, erp, phys, price, unit, serial, sl, fac))
    if code != old_code or name != old_name:
        run("UPDATE transactions SET prod_id=%s, item_name=%s WHERE sl_no=%s AND factory_name=%s", (code, name, sl, fac))
        run("UPDATE requisition_tracking SET prod_id=%s, item_name=%s WHERE factory_name=%s AND prod_id=%s", (code, name, fac, old_code))
    audit("EDIT_INVENTORY", f"{fac} SL {sl}: [{old_code}] {old_name} -> [{code}] {name} [{size}] S/N {serial or '-'}")
    return True


@tx
def delete_item(fac, sl, pid, name):
    run("DELETE FROM inventory WHERE sl_no=%s AND prod_id=%s AND factory_name=%s", (sl, pid, fac))
    audit("DELETE_INVENTORY", f"Deleted {name} [{pid}] from {fac}")
    return True


@tx
def do_import_opening(fac, rows):
    return import_rows(fac, rows)


def inv_master_view():
    st.title("Inventory Master")
    st.caption(f"Search, filter and review stock balances · {html_lib.escape(str(FAC))}")
    inv = qdf_c(f"""SELECT factory_name, sl_no, COALESCE(serial_no,'') AS serial_no, prod_id, item_name,
                  COALESCE(size,'') AS size, department, category,
                  COALESCE(erp_stock,0) AS erp_stock, COALESCE(current_stock,0) AS current_stock,
                  COALESCE(unit_price,0) AS unit_price, erp_status FROM inventory WHERE 1=1{FSQL}
                  ORDER BY factory_name, sl_no""", FP)
    if inv.empty:
        st.info("No inventory items found for this factory.")
        return
    inv["variance"] = inv.current_stock - inv.erp_stock
    inv["erp_value"] = inv.erp_stock * inv.unit_price
    inv["phys_value"] = inv.current_stock * inv.unit_price
    inv["var_value"] = inv.variance * inv.unit_price

    metrics = st.columns(5, gap="small")
    metrics[0].metric("Items", f"{len(inv):,}")
    metrics[1].metric("Low stock (≤ 5)", f"{int((inv.current_stock <= 5).sum()):,}")
    metrics[2].metric("ERP value", f"৳{inv.erp_value.sum():,.0f}")
    metrics[3].metric("Physical value", f"৳{inv.phys_value.sum():,.0f}")
    metrics[4].metric("Variance value", f"৳{inv.var_value.sum():,.0f}")

    filters = st.container(border=True)
    with filters:
        c1, c2 = st.columns([2.2, 1], gap="medium")
        term = c1.text_input(
            "Search inventory", key="inv_search",
            placeholder="Item, serial, ERP code, size, department or category"
        )
        mode = c2.selectbox(
            "Stock view", ["All items", "Low / no stock", "In stock", "Missing size"], key="inv_mode"
        )
    view = inv.copy()
    if mode == "Low / no stock":
        view = view[view.current_stock <= 5]
    elif mode == "In stock":
        view = view[view.current_stock > 0]
    elif mode == "Missing size":
        view = view[view["size"].astype(str).str.strip() == ""]
    if term.strip():
        search_columns = ["item_name", "size", "prod_id", "serial_no", "department", "category"]
        found = view[search_columns].fillna("").astype(str).apply(
            lambda col: col.str.contains(term.strip(), case=False, regex=False)
        ).any(axis=1)
        view = view[found]
    st.caption(f"Showing {len(view):,} of {len(inv):,} inventory items")

    display = view.rename(columns={
        "factory_name": "Factory", "sl_no": "SL No", "serial_no": "Serial No", "prod_id": "ERP Code",
        "item_name": "Item", "size": "Size", "department": "Department", "category": "Category",
        "erp_stock": "ERP stock", "current_stock": "Physical stock", "unit_price": "Unit price (৳)",
        "erp_status": "ERP status", "variance": "Variance", "erp_value": "ERP value (৳)",
        "phys_value": "Physical value (৳)", "var_value": "Variance value (৳)",
    })
    display_columns = [
        "Factory", "SL No", "Serial No", "ERP Code", "Item", "Size", "Department", "Category",
        "ERP stock", "Physical stock", "Variance", "Unit price (৳)", "ERP value (৳)",
        "Physical value (৳)", "Variance value (৳)", "ERP status",
    ]
    display = display[[column for column in display_columns if column in display.columns]]
    st.dataframe(
        display, hide_index=True, use_container_width=True, height=560,
        column_config={
            "ERP stock": st.column_config.NumberColumn(format="%.2f"),
            "Physical stock": st.column_config.NumberColumn(format="%.2f"),
            "Variance": st.column_config.NumberColumn(format="%.2f"),
            "Unit price (৳)": st.column_config.NumberColumn(format="৳ %,.2f"),
            "ERP value (৳)": st.column_config.NumberColumn(format="৳ %,.2f"),
            "Physical value (৳)": st.column_config.NumberColumn(format="৳ %,.2f"),
            "Variance value (৳)": st.column_config.NumberColumn(format="৳ %,.2f"),
        },
    )
    export_buttons(view, "inventory")

_fragment = getattr(st, "fragment", None) or getattr(st, "experimental_fragment", None) or (lambda f: f)


@_fragment
def add_item_form():
    """Add New Item. A fragment: changing a dropdown / typing here reruns only this block, so the page does not
    reload Master List, Edit, Bulk Entry, Queue and ERP Match tabs on every click."""
    st.markdown('<div class="section-title">Add New Item</div>', unsafe_allow_html=True)
    ensure_master_tables()
    # Clear the entry fields after a successful save (must happen before the widgets are created).
    if st.session_state.pop("_add_item_reset", False):
        for _k in ("add_code", "add_name", "add_size", "add_serial", "add_stock", "add_price", "add_sizes"):
            st.session_state.pop(_k, None)

    def _dept_changed():   # Budget Category depends on Department
        st.session_state["add_bud_cat"] = SEL

    # Field order: ERP Code, Item Name, Size | Department, Budget Category, Product Category |
    #              UOM, Initial Stock, Unit Price | Serial No
    c1, c2, c3 = st.columns(3)
    code = c1.text_input("ERP Code (blank = temporary)", key="add_code")
    name = c2.text_input("Item Name*", key="add_name")
    size = c3.text_input("Size (optional)", key="add_size", help="Leave blank if the item has no size.")
    similar_item_alert(FAC, name, size)   # NEW: warns when a very similar item name already exists (never blocks saving)

    d1, d2, d3 = st.columns(3)
    dept = d1.selectbox("Department*", list(DEPARTMENTS), key="add_dept", on_change=_dept_changed)
    bud_cat = d2.selectbox("Budget Category* (from Budget tab)", [SEL] + get_budget_categories(FAC, dept),
                           key="add_bud_cat")
    prod_cat = d3.selectbox("Product Category*", [SEL] + get_product_categories(), key="add_prod_cat")

    u1, u2, u3 = st.columns(3)
    unit = u1.selectbox("UOM*", [SEL] + get_uoms(), key="add_uom")
    stock = u2.number_input("Initial Stock", min_value=0.0, step=1.0, key="add_stock")
    price = u3.number_input("Unit Price (BDT)", min_value=0.0, step=1.0, key="add_price")

    s1, _s2, _s3 = st.columns(3)
    serial = s1.text_input("Serial No (optional, unique per factory)", key="add_serial")

    if st.button("Save Item", key="add_item_save") and guard():
        missing = [lbl for lbl, bad in (("Item Name", not name.strip()),
                                         ("Budget Category", bud_cat == SEL), ("Product Category", prod_cat == SEL),
                                         ("UOM", unit == SEL)) if bad]
        if missing:
            st.error("Required: " + ", ".join(missing) + ". Please fill / select these before saving.")
        else:
            res = add_item(FAC, code, name.strip(), size.strip(), dept, bud_cat, stock, price,
                           serial.strip(), unit, prod_cat)
            if res:
                st.session_state["_add_item_reset"] = True
                done("Stock added to existing item (same name + size, no duplicate)." if res[0] == "exists"
                     else f"New item added: {name.strip()} [{size.strip() or 'no size'}] · {unit} · ERP Code {res[2]}"
                          + (f" — {res[3]}" if res[3] else ""))

    with st.expander("📏 Add this product in several sizes at once"):
        st.caption("Uses the Item Name, ERP Code (as the base: CODE-SIZE), Department, Budget / Product Category, UOM, "
                   "Unit Price and Initial Stock (per size) entered above. Sizes already in the system are skipped.")
        sizes_txt = st.text_input("Sizes (separate with comma)", key="add_sizes", placeholder="e.g. S, M, L, XL, XXL")
        if st.button("➕ Add all sizes", key="add_sizes_btn", use_container_width=True) and guard():
            sizes, seen = [], set()
            for z in re.split(r"[,;\n]+", sizes_txt or ""):
                z = z.strip()
                if z and norm_size(z) and norm_size(z) not in seen:
                    seen.add(norm_size(z))
                    sizes.append(z)
            miss = [lbl for lbl, bad in (("Item Name", not name.strip()), ("Budget Category", bud_cat == SEL),
                                          ("Product Category", prod_cat == SEL), ("UOM", unit == SEL),
                                          ("Sizes", not sizes)) if bad]
            if miss:
                st.error("Required: " + ", ".join(miss) + ".")
            elif len(sizes) > 30:
                st.error("Maximum 30 sizes at a time.")
            else:
                out = add_item_sizes(FAC, code, name.strip(), sizes, dept, bud_cat, stock, price, unit, prod_cat)
                if out:
                    made, skipped = out
                    st.session_state["_add_item_reset"] = True
                    done(f"{len(made)} size(s) added: {', '.join(made) or '-'}"
                         + (f" · already existed (skipped): {', '.join(skipped)}" if skipped else ""))

    with st.expander("➕ Add new Product Category"):
        nc1, nc2 = st.columns([3, 1])
        new_pc = nc1.text_input("New product category name", key="new_pc_name")
        if nc2.button("Add category", key="new_pc_btn") and guard():
            if new_pc.strip() and add_product_category(new_pc.strip()):
                st.session_state["new_pc_name"] = ""
                done(f"Product category '{_clean(new_pc)}' added.")

    with st.expander("➕ Add new UOM"):
        nu1, nu2 = st.columns([3, 1])
        new_uom = nu1.text_input("New UOM (e.g. DOZEN, MTR)", key="new_uom_name")
        if nu2.button("Add UOM", key="new_uom_btn") and guard():
            if new_uom.strip() and add_uom(new_uom.strip()):
                st.session_state["new_uom_name"] = ""
                done(f"UOM '{_clean(new_uom).upper()}' added.")


