# Manager-only diagnostic: tells whether slowness comes from the database server / network or from the app itself.
if st.session_state.get("role") == "Store Manager":
    with st.sidebar:
        if st.checkbox("⏱ Speed check", key="speed_check"):
            _d = st.session_state.get("_dbstat") or {"n": 0, "t": 0.0, "slow": (0.0, "")}
            _total = time.perf_counter() - _RUN_T0
            _p0 = time.perf_counter()
            try:
                q("SELECT 1")
            except Exception:
                pass
            _ping = (time.perf_counter() - _p0) * 1000
            st.caption(f"Page run: **{_total:.2f} s** · Database: **{_d['t']:.2f} s** in **{_d['n']}** calls · "
                       f"Ping: **{_ping:.0f} ms** · Slowest call: {_d['slow'][0] * 1000:.0f} ms")
            if _d["slow"][1]:
                st.caption(f"Slowest: `{_d['slow'][1]}`")
            if _ping > 80 or (_d["n"] and _d["t"] / max(_total, 0.001) > 0.6):
                st.caption("➡ Mostly **database / network**: each call is slow or there are many calls to a far server.")
            else:
                st.caption("➡ Mostly the **app itself** (page building / processing), not the database.")
